export interface Publication {
  readonly id: number;
  readonly title: string;
  readonly summary: string;
  readonly publishedOn: string;
}

export type LookupResult =
  | { readonly ok: true; readonly publication: Publication }
  | { readonly ok: false; readonly message: "Publication not found" };

function copy(publication: Publication): Publication {
  return { ...publication };
}

export class PublicationCatalog {
  private readonly publications: Publication[];

  constructor(publications: readonly Publication[]) {
    const ids = new Set<number>();
    this.publications = publications.map((publication) => {
      if (!Number.isSafeInteger(publication.id) || publication.id <= 0) {
        throw new TypeError("Publication id must be a positive safe integer");
      }
      if (!publication.title.trim() || !publication.summary.trim() || !/^\d{4}-\d{2}-\d{2}$/.test(publication.publishedOn)) {
        throw new TypeError("Publication fields are malformed");
      }
      if (ids.has(publication.id)) throw new RangeError("Publication ids must be unique");
      ids.add(publication.id);
      return copy(publication);
    });
  }

  find(id: number): LookupResult {
    if (!Number.isSafeInteger(id) || id <= 0) return { ok: false, message: "Publication not found" };
    const publication = this.publications[id];
    return publication
      ? { ok: true, publication: copy(publication) }
      : { ok: false, message: "Publication not found" };
  }

  list(): Publication[] {
    return this.publications.map(copy);
  }
}

