import { Publication, PublicationCatalog, LookupResult } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsAs(fn: () => unknown, kind: typeof TypeError | typeof RangeError, message: string): void {
  try { fn(); } catch (error) { if (error instanceof kind) return; throw new Error(`${message}: wrong error`); }
  throw new Error(`${message}: did not throw`);
}

const empty = new PublicationCatalog([]);
const emptyList = empty.list();
equal(emptyList.length, 0, "empty catalog lists empty");
assert(emptyList !== empty.list(), "empty list arrays are fresh");
const missing: LookupResult = empty.find(1);
equal(missing.ok, false, "empty lookup fails");
if (!missing.ok) equal(missing.message, "Publication not found", "failure message");

const source: Publication[] = [
  { id: 1, title: " First ", summary: "Summary one", publishedOn: "2025-01-09" },
  { id: Number.MAX_SAFE_INTEGER, title: "Second", summary: " S ", publishedOn: "0000-99-99" }
];
const catalog = new PublicationCatalog(source);
source.push({ id: 3, title: "Later", summary: "Later", publishedOn: "2025-01-01" });
(source[0] as { title: string }).title = "mutated";
const listed = catalog.list();
equal(listed.length, 2, "constructor array copied");
equal(listed[0].title, " First ", "constructor entry copied");
equal(listed[1].id, Number.MAX_SAFE_INTEGER, "safe integer boundary accepted");
equal(listed[1].publishedOn, "0000-99-99", "date validation is exact shape");

(listed[0] as { title: string }).title = "changed result";
listed.pop();
const listedAgain = catalog.list();
equal(listedAgain.length, 2, "returned array mutation isolated");
equal(listedAgain[0].title, " First ", "returned object mutation isolated");
assert(listedAgain !== catalog.list(), "list returns fresh arrays");
assert(listedAgain[0] !== catalog.list()[0], "list returns fresh objects");

const found = catalog.find(1);
assert(found.ok, "valid id found");
if (found.ok) {
  equal(found.publication.summary, "Summary one", "found publication data");
  (found.publication as { summary: string }).summary = "changed";
}
const foundAgain = catalog.find(1);
assert(foundAgain.ok, "publication remains findable");
if (foundAgain.ok) equal(foundAgain.publication.summary, "Summary one", "find result is defensive");

for (const id of [0, -1, 1.5, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
  const result = catalog.find(id);
  equal(result.ok, false, `malformed lookup ${String(id)} fails`);
  if (!result.ok) equal(result.message, "Publication not found", "malformed lookup message");
}

throwsAs(() => new PublicationCatalog([{ id: 0, title: "T", summary: "S", publishedOn: "2025-01-01" }]), TypeError, "nonpositive id");
throwsAs(() => new PublicationCatalog([{ id: 1.2, title: "T", summary: "S", publishedOn: "2025-01-01" }]), TypeError, "fractional id");
throwsAs(() => new PublicationCatalog([{ id: 1, title: "   ", summary: "S", publishedOn: "2025-01-01" }]), TypeError, "blank title");
throwsAs(() => new PublicationCatalog([{ id: 1, title: "T", summary: "\t", publishedOn: "2025-01-01" }]), TypeError, "blank summary");
throwsAs(() => new PublicationCatalog([{ id: 1, title: "T", summary: "S", publishedOn: "2025-1-01" }]), TypeError, "malformed date");
throwsAs(() => new PublicationCatalog([
  { id: 2, title: "A", summary: "A", publishedOn: "2025-01-01" },
  { id: 2, title: "B", summary: "B", publishedOn: "2025-01-02" }
]), RangeError, "duplicate ids");

